import{_ as e,o as l,c as a,ao as d}from"./chunks/framework.DuTZfSXl.js";const x=JSON.parse('{"title":"Platforms and limits","description":"","frontmatter":{},"headers":[],"relativePath":"reference/platforms.md","filePath":"reference/platforms.md","lastUpdated":null}'),n={name:"reference/platforms.md"};function s(i,t,r,o,f,c){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="Platforms-and-limits" tabindex="-1">Platforms and limits <a class="header-anchor" href="#Platforms-and-limits" aria-label="Permalink to &quot;Platforms and limits {#Platforms-and-limits}&quot;">​</a></h1><p>Which transform works on which number type and platform. ✓ means implemented and covered by the test suite; ◐ means implemented but not tuned or not tested on that platform; – means not available.</p><h2 id="Transforms" tabindex="-1">Transforms <a class="header-anchor" href="#Transforms" aria-label="Permalink to &quot;Transforms {#Transforms}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">transform</th><th style="text-align:left;">CPU, <code>Float32</code>/<code>Float64</code></th><th style="text-align:left;">CPU, other <code>AbstractFloat</code>s (<code>BigFloat</code>, <code>Double64</code>, <code>Float128</code>)</th><th style="text-align:left;">GPU (KernelAbstractions)</th><th style="text-align:left;">libfftl</th></tr></thead><tbody><tr><td style="text-align:left;">complex DFT (<code>fft</code>, <code>bfft</code>, <code>ifft</code>)</td><td style="text-align:left;">✓ threads, SIMD</td><td style="text-align:left;">✓ one thread</td><td style="text-align:left;">✓ tuned on Metal, measured on CUDA</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">real input <code>rfft</code>, <code>irfft</code>, <code>brfft</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓ at about complex speed</td><td style="text-align:left;">✓ <code>r2c</code>, <code>c2r</code>, also in place and split</td></tr><tr><td style="text-align:left;">DCT-II, the orthonormal <code>dct</code>/<code>idct</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">DCT-I, DCT-III, DCT-IV</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">◐ partly tuned</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">DST-II</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">DST-I, DST-III, DST-IV</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">◐ partly tuned</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">DHT, <code>R2HC</code>, <code>HC2R</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">◐ not tuned</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">batched 1D passes (<code>plan_pass</code>, <code>plan_r2r_pass</code>)</td><td style="text-align:left;">✓</td><td style="text-align:left;">–</td><td style="text-align:left;">–</td><td style="text-align:left;">–</td></tr><tr><td style="text-align:left;">any rank and any subset of dimensions</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">any length (Bluestein above prime factor 31)</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr></tbody></table><h2 id="Platforms" tabindex="-1">Platforms <a class="header-anchor" href="#Platforms" aria-label="Permalink to &quot;Platforms {#Platforms}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">platform</th><th style="text-align:left;">status</th></tr></thead><tbody><tr><td style="text-align:left;">Apple M1 Max (arm64, macOS)</td><td style="text-align:left;">development machine; codelets use the <code>FCADD</code>/<code>FCMLA</code> complex instructions; GPU via Metal</td></tr><tr><td style="text-align:left;">AMD EPYC 7763 (Zen 3, x86-64 with AVX2, Linux)</td><td style="text-align:left;">x86-64 development machine</td></tr><tr><td style="text-align:left;">AMD EPYC 7702 (Zen 2, x86-64 with AVX2, Linux)</td><td style="text-align:left;">x86-64 machine of the <a href="/FFTL.jl/previews/PR26/reference/benchmarks#Benchmarks">benchmarks</a></td></tr><tr><td style="text-align:left;">Intel Core i7-1185G7 (Tiger Lake, x86-64 with AVX-512, Linux)</td><td style="text-align:left;">512-bit kernels tested; radix rules not retuned for AVX-512</td></tr><tr><td style="text-align:left;">Linux and macOS in CI</td><td style="text-align:left;">quick tests on every push to <code>main</code> and on pull requests; full tests weekly</td></tr><tr><td style="text-align:left;">NVIDIA RTX A6000</td><td style="text-align:left;">GPU via CUDA, measured against cuFFT</td></tr><tr><td style="text-align:left;">AMD, Intel GPUs</td><td style="text-align:left;">not tested</td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;">not tested</td></tr></tbody></table><h2 id="Julia-versions" tabindex="-1">Julia versions <a class="header-anchor" href="#Julia-versions" aria-label="Permalink to &quot;Julia versions {#Julia-versions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">version</th></tr></thead><tbody><tr><td style="text-align:left;">the package</td><td style="text-align:left;">Julia 1.10 and newer (weekly CI on 1.10)</td></tr><tr><td style="text-align:left;">the libfftl build</td><td style="text-align:left;">Julia 1.12 and newer with <code>juliac</code></td></tr></tbody></table><h2 id="Limits" tabindex="-1">Limits <a class="header-anchor" href="#Limits" aria-label="Permalink to &quot;Limits {#Limits}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">quantity</th><th style="text-align:left;">limit</th></tr></thead><tbody><tr><td style="text-align:left;">element types, complex</td><td style="text-align:left;"><code>ComplexF32</code>, <code>ComplexF64</code>; any <code>Complex{T}</code> with <code>T</code> a floating-point type on the generic path</td></tr><tr><td style="text-align:left;">element types, real</td><td style="text-align:left;"><code>Float32</code>, <code>Float64</code>, and every other <code>AbstractFloat</code> on the generic path; <code>Float16</code> and integers are converted</td></tr><tr><td style="text-align:left;">rank</td><td style="text-align:left;">any</td></tr><tr><td style="text-align:left;">length of a dimension</td><td style="text-align:left;">any; memory is the limit</td></tr><tr><td style="text-align:left;">threads</td><td style="text-align:left;"><code>Threads.nthreads()</code> by default; a plan may use fewer</td></tr><tr><td style="text-align:left;">transforms on the GPU</td><td style="text-align:left;">out of place; a plan holds about two buffers of the array&#39;s size</td></tr><tr><td style="text-align:left;">libfftl precision</td><td style="text-align:left;"><code>float</code> and <code>double</code> (FFTW3&#39;s <code>fftw_</code> and <code>fftwf_</code> functions; no <code>fftwl_</code>, <code>fftwq_</code>)</td></tr><tr><td style="text-align:left;">libfftl interface</td><td style="text-align:left;">FFTW3&#39;s C, legacy Fortran and Fortran 2003 interfaces; layouts other than one contiguous array are copied</td></tr><tr><td style="text-align:left;">libfftl threads</td><td style="text-align:left;">fixed at build time</td></tr></tbody></table><p>Numbers that are not in this table, such as the largest transform that fits on a particular machine, depend on the machine and are reported with the <a href="/FFTL.jl/previews/PR26/reference/benchmarks#Benchmarks">benchmarks</a>.</p>',11)])])}const h=e(n,[["render",s]]);export{x as __pageData,h as default};
